// RenewCertificateWithBody Renew the client certificate
//
// Signs a certificate for a key the operator generated (ECDSA P-256 or P-384, or Ed25519),
// valid for 30 days. The key must differ from the current certificate's. Keep using the
// current certificate until the new one is installed: the first request made with the new
// one retires the old.
//
// Takes any type of body and a specified content type.
//
// Corresponds with POST /v1/certificate (the `RenewCertificate` operationId).
func (c *Client) RenewCertificateWithBody(ctx context.Context, contentType string, body io.Reader, reqEditors ...RequestEditorFn) (*http.Response, error) {
	req, err := NewRenewCertificateRequestWithBody(c.Server, contentType, body)
	if err != nil {
		return nil, err
	}
	req = req.WithContext(ctx)
	if err := c.applyEditors(ctx, req, reqEditors); err != nil {
		return nil, err
	}
	return c.Client.Do(req)
}

